insert into @tabpro (produto,fator_p) values ('T6059137',2)
insert into @tabpro (produto,fator_p) values ('T6059138',3)
insert into @tabpro (produto,fator_p) values ('T6059139',3)

select TB.*, FP.*, PP.*
--UPDATE PP 
--SET VALOR_PROPRIEDADE = 
--CASE 
--	WHEN (FP.UNOUS_NIVEL = 'FATOR_P') and (TB.FATOR_P < 3) THEN 'P1/P2'
--	WHEN (FP.UNOUS_NIVEL = 'FATOR_P') and (TB.FATOR_P > 2) THEN 'P3/P4'
--	ELSE PP.VALOR_PROPRIEDADE
--END
from produtos p
INNER JOIN 
(SELECT GRIFFE, LINHA, GRUPO_PRODUTO, SUBGRUPO_PRODUTO, UNOUS_NIVEL FROM CAE_PRODUTOS_FATOR_P
GROUP BY GRIFFE, LINHA, GRUPO_PRODUTO, SUBGRUPO_PRODUTO, UNOUS_NIVEL) AS FP
	ON FP.GRIFFE=P.GRIFFE AND FP.LINHA=P.LINHA AND FP.GRUPO_PRODUTO=P.GRUPO_PRODUTO AND FP.SUBGRUPO_PRODUTO=P.SUBGRUPO_PRODUTO
inner join @tabpro tb on tb.produto = p.produto 
INNER JOIN PROP_PRODUTOS PP ON PP.PRODUTO=TB.produto AND PP.PROPRIEDADE='00107'
where p.fator_p = tb.fator_p and p.DATA_PARA_TRANSFERENCIA>'20220613'

